import { screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../types";
import { MemoryClearedEventInfo } from "./MemoryClearedEventInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({ title, children }: { title: string; children: React.ReactNode }) => (
    <div>
      <h1>{title}</h1>
      {children}
    </div>
  ),
}));

const event: ConversationEvent = {
  id: "e1",
  conversationEventType: ConversationEventType.MemoryCleared,
  name: "card_replace.replacement_reason",
  slotValue: null,
  actionText: "",
  flowId: "",
  stepId: "",
  timestamp: "2020-01-01T00:00:00.000Z",
  originalTimestamp: 0,
  metadata: { parseData: {} },
  __typename: "ConversationEvent",
};

describe("MemoryClearedEventInfo", () => {
  it("omits the value field", () => {
    renderWithProviders(<MemoryClearedEventInfo event={event} onClose={() => undefined} />);
    expect(screen.getByRole("heading", { name: "Memory cleared" })).toBeInTheDocument();
    expect(screen.getByText("Name")).toBeInTheDocument();
    expect(screen.queryByText("Value")).toBeNull();
  });
});
